-- Pinças inox e caneladas: contorno sem halo branco
INSERT INTO "stored_files" ("id","area","fileName","mimeType","sizeBytes","data","createdAt")
SELECT gen_random_uuid(),'products','edel-pi-inx-pf-v4.webp','image/webp',11610,decode('','hex'),now() WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName"='edel-pi-inx-pf-v4.webp');
